      targetObject.window.__CLASSICAL_NOMINAL_CONSTRUCTION_FRAME__ = null;
      targetObject.window.__CLASSICAL_NOMINAL_CONSTRUCTION_PARADIGM_PLAN__ = null;
      targetObject.window.__CLASSICAL_NOMINAL_CONSTRUCTION_PARADIGM_COORDINATES__ = null;
      targetObject.window.__CLASSICAL_NOMINAL_CONSTRUCTION_PARADIGM_COORDINATE_BATCHES__ = null;
      targetObject.window.__CLASSICAL_DENOMINAL_VNC_FRAME__ = null;
      targetObject.window.__CLASSICAL_ADVERBIAL_NUCLEAR_RESULT__ = null;
