        targetObject.window.__CLASSICAL_PERSONAL_NAME_SENTENCE_OPERATION_RECEIPT__ =
          personalNameSentenceOperation?.applicationResult || null;
        targetObject.window.__CLASSICAL_PERSONAL_NAME_SENTENCE_OPERATION_RESULT__ =
          personalNameSentenceOperation?.canonicalResult || null;
